/**
 * Fieldset. A named group of fields: "Shipping address", "Notifications".
 * The legend is the group's name (and a screen reader says it before each
 * field inside); a description can follow it. `disabled` disables every
 * control inside at once. Base UI Fieldset.
 */
import type { ReactNode } from "react";
import { Fieldset as BaseFieldset } from "@base-ui/react/fieldset";
import "./fieldset.css";

export interface FieldsetProps {
  /** The group's name. */
  legend: string;
  /** A line under the legend. */
  description?: ReactNode;
  children: ReactNode;
  /** Disable every control inside. */
  disabled?: boolean;
}

export function Fieldset({ legend, description, children, disabled }: FieldsetProps) {
  return (
    <BaseFieldset.Root className="echo-fieldset" {...(disabled !== undefined ? { disabled } : {})}>
      <BaseFieldset.Legend className="echo-fieldset__legend">{legend}</BaseFieldset.Legend>
      {description ? <p className="echo-fieldset__description">{description}</p> : null}
      <div className="echo-fieldset__body">{children}</div>
    </BaseFieldset.Root>
  );
}

/**
 * Fieldset. A legend in the section voice over its fields; a hairline above
 * separates it from the group before.
 */
.echo-fieldset {
  display: grid;
  gap: var(--echo-space-6);
  min-width: 0;
  margin: 0;
  padding: var(--echo-space-9) 0 0;
  border: 0;
  border-block-start: var(--echo-border-hairline, 1px) solid var(--echo-seam);
}
/* Base UI's Legend is an element in the flow that names the fieldset
   (aria-labelledby), not a native legend on its border. */
.echo-fieldset__legend {
  display: block;
  width: 100%;
  padding: 0;
  font-size: var(--echo-text-md);
  font-weight: var(--echo-weight-semibold, 600);
  color: var(--echo-text);
}
.echo-fieldset__description {
  margin: calc(-1 * var(--echo-space-4)) 0 0;
  font-size: var(--echo-text-sm);
  color: var(--echo-text-dim);
}
.echo-fieldset__body {
  display: grid;
  gap: var(--echo-space-8);
  min-width: 0;
}
.echo-fieldset[data-disabled] {
  opacity: 0.6;
}
@media (forced-colors: active) {
  .echo-fieldset {
    border-block-start-color: CanvasText;
  }
}
